import Header from "@/components/Header";
import Footer from "@/components/Footer";
import Link from "next/link";
import { notFound } from "next/navigation";
import {
  getAdjacentProjects,
  getProjectBySlug,
} from "@/lib/projects";

export const revalidate = 60;

export default async function ProjectPage({
  params,
}: {
  params: Promise<{ slug: string }>;
}) {
  const { slug } = await params;

  const project = await getProjectBySlug(slug);

  if (!project) {
    notFound();
  }

  const { previous, next } = await getAdjacentProjects(project.id);

  const coverImage =
    project.cover_image ??
    project.hero_image ??
    project.images[0]?.image_url ??
    null;

  const galleryImages = project.images.filter(
    (image) => image.image_url !== coverImage
  );

  const projectMeta = [
    project.location,
    project.area,
    project.year ? String(project.year) : null,
  ]
    .filter(Boolean)
    .join(" | ");

  const paragraphs = (project.description ?? "")
    .split(/\n\s*\n/)
    .map((text) => text.trim())
    .filter(Boolean);

  return (
    <>
      <Header />

      <main className="page-shell">
        <h1 className="project-title">{project.title}</h1>

        {coverImage ? (
          <div className="project-hero real-project-hero">
            <img
              src={coverImage}
              alt={project.title}
            />
          </div>
        ) : (
          <div className="project-hero">
            IMAGEN PRINCIPAL
          </div>
        )}

        <section className="project-copy">
          {projectMeta && <h2>{projectMeta}</h2>}

          {paragraphs.map((paragraph, index) => (
            <p key={index}>{paragraph}</p>
          ))}
        </section>

        {galleryImages.length > 0 && (
          <section className="gallery real-gallery">
            {galleryImages.map((image) => (
              <figure className="img" key={image.id}>
                <img
                  src={image.image_url}
                  alt={image.caption || project.title}
                  loading="lazy"
                />
              </figure>
            ))}
          </section>
        )}

        {(previous || next) && (
          <nav
            className="project-navigation"
            aria-label="Navegación entre proyectos"
          >
            {previous ? (
              <Link
                href={`/proyectos/${previous.slug}`}
                className="project-nav-button"
                aria-label={`Ir a ${previous.title}`}
              >
                ‹
              </Link>
            ) : (
              <span />
            )}

            {next ? (
              <Link
                href={`/proyectos/${next.slug}`}
                className="project-nav-button"
                aria-label={`Ir a ${next.title}`}
              >
                ›
              </Link>
            ) : (
              <span />
            )}
          </nav>
        )}
      </main>

      <Footer />

      <style>{`
        .real-project-hero{
          overflow:hidden;
          position:relative;
          display:block;
        }

        .real-project-hero img{
          width:100%;
          height:100%;
          object-fit:cover;
          object-position:center;
        }

        .real-gallery .img{
          overflow:hidden;
          background:#fff;
          margin:0;
        }

        .real-gallery .img img{
          width:100%;
          height:100%;
          object-fit:cover;
        }

        .project-navigation{
          position:fixed;
          left:0;
          right:0;
          top:50%;
          transform:translateY(-50%);
          z-index:30;
          display:flex;
          justify-content:space-between;
          pointer-events:none;
        }

        .project-nav-button{
          width:42px;
          height:42px;
          display:grid;
          place-items:center;
          background:rgba(0,0,0,.45);
          color:#fff;
          font-size:30px;
          font-weight:300;
          pointer-events:auto;
        }

        @media (max-width:620px){
          .project-navigation{
            top:auto;
            bottom:30px;
            transform:none;
          }
        }
      `}</style>
    </>
  );
}
